import csv,json,pathlib,zipfile,unittest
P=pathlib.Path(__file__).parent
rows=[
 dict(city='Paris',boundary='Paris department/municipality',year=2022,metric='vacant dwellings (census)',value=136957,denominator=1399122,source='https://www.insee.fr/fr/statistiques/8581193?geo=DEP-75',status='verified',note='Census vacancy; includes different forms of vacancy.'),
 dict(city='Paris',boundary='Paris department/municipality',year=2022,metric='secondary or occasional dwellings',value=136693,denominator=1399122,source='https://www.insee.fr/fr/statistiques/8581193?geo=DEP-75',status='verified',note='Not necessarily available for conversion.'),
 dict(city='London',boundary='Greater London',year=2025,metric='empty homes (Council Tax)',value=105138,denominator='',source='https://www.london.gov.uk/who-we-are/what-london-assembly-does/london-assembly-research-unit-publications/empty-homes-london',status='verified',note='Council Tax classification; do not compare directly to census.'),
 dict(city='London',boundary='Greater London',year=2025,metric='long-term empty homes (>6 months)',value=47287,denominator='',source='https://www.london.gov.uk/who-we-are/what-london-assembly-does/london-assembly-press-releases/number-empty-homes-london-continues-rise',status='verified',note='Subset of empty homes, not additive.'),
 dict(city='New York',boundary='New York City (five boroughs)',year=2023,metric='available vacant rental units',value=33210,denominator=2357000,source='https://www.nyc.gov/assets/hpd/downloads/pdfs/about/2023-nychvs-selected-initial-findings.pdf',status='verified',note='Market rental vacancies; NOT recoverable stock.'),
 dict(city='Tokyo',boundary='Tokyo Metropolis/prefecture',year=2023,metric='vacant dwellings (housing survey)',value=896500,denominator='',source='https://www.juutakuseisaku.metro.tokyo.lg.jp/documents/d/juutakuseisaku/jyuuseishinkikakubukai_tokyonojutakujijo_260424',status='verified',note='Includes 629,000 for rent and 43,800 for sale; 214,200 other; categories not additive to opportunities.'),
 dict(city='Tokyo',boundary='Tokyo Metropolis/prefecture',year=2023,metric='vacant other (not for sale/rent or second homes)',value=214200,denominator='',source='https://www.juutakuseisaku.metro.tokyo.lg.jp/documents/d/juutakuseisaku/jyuuseishinkikakubukai_tokyonojutakujijo_260424',status='verified',note='Subset of all vacancies; not necessarily habitable.'),
 dict(city='Cairo',boundary='Cairo Governorate vs Greater Cairo unresolved',year='',metric='comparable vacant dwelling inventory',value='',denominator='',source='',status='missing',note='No validated city-level figure; obtain CAPMAS tables and settle boundary first.'),
]
with (P/'city_evidence.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
# Screening ranges deliberately NOT predictions. Avoid NYC rental market and secondary homes.
bases={'Paris':136957,'London':47287,'Tokyo':214200}
with (P/'screening_scenarios.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['city','eligible_inventory_proxy','screening_fraction_ASSUMPTION','screened_units_NOT_verified_recoverable','interpretation'])
 for city,base in bases.items():
  for r in [0.05,0.15,0.30]:w.writerow([city,base,r,round(base*r),'Upper-level screening arithmetic only; NOT available housing'])
(P/'README.md').write_text('''# UNIRA V5.1 — Metropolitan Housing Evidence Registry\n\n## Research advancement\nFive-city framework: **Paris, Greater London, New York City, Tokyo Metropolis, Cairo**. Four have verified city/region-specific housing indicators; Cairo remains explicitly missing. This is not a harmonized vacancy dataset and is not empirical calibration of intervention costs or carbon.\n\n### Important improvements\n* Tokyo now has verified metropolitan data: **896,500** vacant dwellings (2023), including **629,000** rental vacancies, **43,800** sale vacancies, **9,600** second homes, **214,200** other vacancies. Total components sum to 896,600 owing to source rounding. Do not sum as if exact. Tokyo source also gives **105,000** vacancies with damage/deterioration, but this does not establish structural suitability.\n* London 2025: **105,138** empty homes; **47,287** long-term empty homes, a subset. Do not add.\n* Paris 2022: **136,957** census vacant homes; **136,693** secondary/occasional, separate categories.\n* NYC 2023: **33,210** rental units available; vacancy rate **1.41%**. Ordinary market turnover, not an idle-housing recovery pool.\n* Cairo: **missing**. A country-level figure would be misleading.\n\n### Comparability and research design\nCity boundaries differ; indicators measure different concepts, surveys/administrative records differ and years vary. **No cross-city ranking of 'wasted homes' is defensible.** Screening scenarios (5/15/30%) are arbitrary sensitivity calculations only, applied to different proxy stocks; never sum or treat as projections.\n\n### Housing optimisation specification\nFor each building and household category, gather verified: legal status/consent, dwelling size, accessibility, location/travel time, structural condition, renovation scope, local construction/retrofit costs, embodied carbon and operating-energy baseline, life-cycle horizon, household preferences and actual unmet need. Build feasible matches; solve integer optimisation for quality-constrained minimum lifecycle cost/carbon; compare with realistic existing-policy counterfactual; run uncertainty analysis.\n\n### Next research tasks\n1. Obtain CAPMAS Cairo Governorate and Greater Cairo housing census tables, definitions and dates.\n2. Obtain comparable subregional building condition, household crowding and energy-performance data for all five.\n3. Acquire audited local unit costs and lifecycle carbon factors; do not import England-wide costs into other cities without explicit transfer modelling.\n4. Publish dataset version, provenance, transformation scripts and uncertainty intervals.\n\n### Source URLs\nSee `city_evidence.csv`; all primary governmental/municipal sources. Source years are data reference years, not publication years.\n''',encoding='utf-8')
(P/'test_evidence.py').write_text('''import csv, pathlib, unittest\nP=pathlib.Path(__file__).parent\nclass TestEvidence(unittest.TestCase):\n def setUp(self):\n  with (P/'city_evidence.csv').open() as f:self.rows=list(csv.DictReader(f))\n def test_five_cities(self):self.assertEqual({r['city'] for r in self.rows},{'Paris','London','New York','Tokyo','Cairo'})\n def test_missing_cairo(self):self.assertEqual(next(r for r in self.rows if r['city']=='Cairo')['status'],'missing')\n def test_provenance(self):self.assertTrue(all(r['source'].startswith('https://') for r in self.rows if r['status']=='verified'))\n def test_london_subset(self):\n  x=[r for r in self.rows if r['city']=='London'];self.assertLess(int(x[1]['value']),int(x[0]['value']))\n def test_tokyo_subset(self):\n  x=[r for r in self.rows if r['city']=='Tokyo'];self.assertLess(int(x[1]['value']),int(x[0]['value']))\nif __name__=='__main__':unittest.main()\n''')
with zipfile.ZipFile('/mnt/data/unira/UNIRA_V51_Metropolitan_Evidence.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in P.iterdir():z.write(f,arcname=f.name)
print('Created zip')
